/**
 * The region this application's CICS programs run in (#4343): every program's facade (handleTransaction,
 * handleLink) runs its task here -- one temporary storage, and a LINK / XCTL reaching the other programs
 * through their services' runTask, as the CSD-defined programs of a CICS region reach each other. Spring makes
 * it once, which deploys it (CicsTask.deploy); a test harness joins a region of its own instead (CicsTask.join).
 * Its clock is the mainframe's, as MainframeClock's (#3824): `gitgalaxy.clock` (an ISO local date-time) when
 * set, else the wall clock in `gitgalaxy.zone`, else `gitgalaxy.culture.zone`, else UTC -- never the JVM's.
 */
@Component
public class CicsRegion implements CicsTask.Programs {

    static final Set<String> PROGRAMS = Set.of("COACCT01", "COACTUPC", "COACTVWC", "COADM01C", "COBIL00C", "COCRDLIC", "COCRDSLC", "COCRDUPC", "CODATE01", "COMEN01C", "COPAUA0C", "COPAUS0C", "COPAUS1C", "COPAUS2C", "CORPT00C", "COSGN00C", "COTRN00C", "COTRN01C", "COTRN02C", "COTRTLIC", "COTRTUPC", "COUSR00C", "COUSR01C", "COUSR02C", "COUSR03C");
    static final Set<String> TRANSACTIONS = Set.of("CA00", "CAUP", "CAVW", "CB00", "CC00", "CCDL", "CCLI", "CCUP", "CDRA", "CDRD", "CM00", "CP00", "CPVD", "CPVS", "CR00", "CT00", "CT01", "CT02", "CTLI", "CTTU", "CU00", "CU01", "CU02", "CU03");

    private final ApplicationContext context;

    public CicsRegion(ApplicationContext context, @Value("${gitgalaxy.clock:}") String pinned,
                      @Value("${gitgalaxy.zone:${gitgalaxy.culture.zone:UTC}}") String zoneId) {
        this.context = context;
        ZoneId zone = ZoneId.of(zoneId == null || zoneId.isBlank() ? "UTC" : zoneId.trim());
        String at = pinned == null ? "" : pinned.trim();
        CicsTask.deploy(new CicsTask.LocalRegion(this, null,
                at.isEmpty() ? () -> LocalDateTime.now(zone) : () -> LocalDateTime.parse(at)));
    }

    @Override
    public boolean defined(String program) {
        return PROGRAMS.contains(program);
    }

    @Override
    public boolean transaction(String transid) {
        return TRANSACTIONS.contains(transid);
    }

    @Override
    public void run(String program, CicsTask task) {
        switch (program) {
            case "COACCT01" -> context.getBean(Coacct01Service.class).runTask(task);
            case "COACTUPC" -> context.getBean(CoactupcService.class).runTask(task);
            case "COACTVWC" -> context.getBean(CoactvwcService.class).runTask(task);
            case "COADM01C" -> context.getBean(Coadm01cService.class).runTask(task);
            case "COBIL00C" -> context.getBean(Cobil00cService.class).runTask(task);
            case "COCRDLIC" -> context.getBean(CocrdlicService.class).runTask(task);
            case "COCRDSLC" -> context.getBean(CocrdslcService.class).runTask(task);
            case "COCRDUPC" -> context.getBean(CocrdupcService.class).runTask(task);
            case "CODATE01" -> context.getBean(Codate01Service.class).runTask(task);
            case "COMEN01C" -> context.getBean(Comen01cService.class).runTask(task);
            case "COPAUA0C" -> context.getBean(Copaua0cService.class).runTask(task);
            case "COPAUS0C" -> context.getBean(Copaus0cService.class).runTask(task);
            case "COPAUS1C" -> context.getBean(Copaus1cService.class).runTask(task);
            case "COPAUS2C" -> context.getBean(Copaus2cService.class).runTask(task);
            case "CORPT00C" -> context.getBean(Corpt00cService.class).runTask(task);
            case "COSGN00C" -> context.getBean(Cosgn00cService.class).runTask(task);
            case "COTRN00C" -> context.getBean(Cotrn00cService.class).runTask(task);
            case "COTRN01C" -> context.getBean(Cotrn01cService.class).runTask(task);
            case "COTRN02C" -> context.getBean(Cotrn02cService.class).runTask(task);
            case "COTRTLIC" -> context.getBean(CotrtlicService.class).runTask(task);
            case "COTRTUPC" -> context.getBean(CotrtupcService.class).runTask(task);
            case "COUSR00C" -> context.getBean(Cousr00cService.class).runTask(task);
            case "COUSR01C" -> context.getBean(Cousr01cService.class).runTask(task);
            case "COUSR02C" -> context.getBean(Cousr02cService.class).runTask(task);
            case "COUSR03C" -> context.getBean(Cousr03cService.class).runTask(task);
            default -> throw new IllegalStateException("no service runs program " + program);
        }
    }
}
